INSERT INTO employees (tenant_id, full_name, active)
SELECT 1, seed.full_name, true
FROM (VALUES
  ('ARTURO'),
  ('CARLOS R.'),
  ('CHORE'),
  ('CRISTAL'),
  ('CRISTIAN'),
  ('DAVID'),
  ('ERASMO'),
  ('LUPE'),
  ('MANUEL'),
  ('PANCHO'),
  ('REINA'),
  ('RICARDO'),
  ('TAVO'),
  ('VALE'),
  ('WENDY'),
  ('WICHO'),
  ('YUREM')
) AS seed(full_name)
WHERE NOT EXISTS (
  SELECT 1 FROM employees e
  WHERE e.tenant_id = 1 AND e.full_name = seed.full_name
);

