INSERT INTO payroll_entries (
  tenant_id, payroll_period_id, employee_id, cars_washed, base_salary, cars_bonus_rate,
  cars_bonus, commissions, tips_pool_share, advances_deducted, net_pay
)
SELECT
  1, pp.id, e.id, seed.cars_washed, seed.base_salary, seed.cars_bonus_rate,
  seed.cars_bonus, seed.commissions, seed.tips_pool_share, seed.advances_deducted, seed.net_pay
FROM seed
JOIN payroll_periods pp
  ON pp.tenant_id = 1 AND pp.start_date = seed.start_date AND pp.end_date = seed.end_date
JOIN employees e
  ON e.tenant_id = 1 AND e.full_name = seed.employee_name
ON CONFLICT (tenant_id, payroll_period_id, employee_id) DO UPDATE
SET cars_washed = excluded.cars_washed,
    base_salary = excluded.base_salary,
    cars_bonus_rate = excluded.cars_bonus_rate,
    cars_bonus = excluded.cars_bonus,
    commissions = excluded.commissions,
    tips_pool_share = excluded.tips_pool_share,
    advances_deducted = excluded.advances_deducted,
    net_pay = excluded.net_pay,
    updated_at = now();
